head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[bigDecimal > M > compare]<br/>현재 bigDecimal 데이터와 입력받은 bigDecimal 데이터를 비교하여 더 큰 수 또는 더 작은 수를 반환합니다.",
    "validation" : [
        "data(필수) 파라미터로 비교 대상이 되는 bigDecimal 데이터를 설정할 수 있어야 합니다.",
        "type(선택) 파라미터를 false 로 설정 시 두 값 중 더 큰 수(최대값)를 반환해야 합니다.",
        "type(선택) 파라미터를 true 로 설정 시 두 값 중 더 작은 수(최소값)를 반환해야 합니다.",
        "type(선택) 파라미터 생략 시 기본값 false 로 동작하여 더 큰 수(최대값)를 반환해야 합니다.",
        "연산 중 오류가 발생하면 NaN 을 나타내는 bigDecimal 을 반환해야 합니다.",
    ]
}



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



scwin.btn_compareMax_onclick = function () {
    let a = $p.bigDecimal("111111111111111111111111111111");
    let b = $p.bigDecimal("11111");
    let ret = a.compare(b, false);
    wf_body_bottom.getObj("scwin").setReturnValue("a.compare(b, false) : " + ret.toString());
}



scwin.btn_compareMin_onclick = function () {
    let a = $p.bigDecimal("111111111111111111111111111111");
    let b = $p.bigDecimal("11111");
    let ret = a.compare(b, true);
    wf_body_bottom.getObj("scwin").setReturnValue("a.compare(b, true) : " + ret.toString());
}



scwin.btn_compareOmit_onclick = function () {
    let a = $p.bigDecimal("111111111111111111111111111111");
    let b = $p.bigDecimal("11111");
    let ret = a.compare(b);
    wf_body_bottom.getObj("scwin").setReturnValue("a.compare(b) : " + ret.toString());
}



scwin.btn_compareNaN_onclick = function () {
    let a = $p.bigDecimal("abc");
    let b = $p.bigDecimal("10");
    let ret = a.compare(b);
    wf_body_bottom.getObj("scwin").setReturnValue("a('abc').compare(b) : " + ret.toString());
}
